CREATE TABLE "app_settings" ("key" TEXT NOT NULL, "value" TEXT NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("key"));
CREATE TABLE "folders" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "color" TEXT NULL, "icon" TEXT NULL, "parent_folder_id" TEXT NULL REFERENCES folders (id), "sort_order" INTEGER NOT NULL DEFAULT 0, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "notification_settings" ("id" TEXT NOT NULL, "task_id" TEXT NOT NULL REFERENCES tasks (id), "enabled" INTEGER NOT NULL CHECK ("enabled" IN (0, 1)), "days_before_due" INTEGER NOT NULL, "notify_time" TEXT NOT NULL, "scheduled_at" INTEGER NULL, PRIMARY KEY ("id"));
CREATE TABLE "sub_tasks" ("id" TEXT NOT NULL, "task_id" TEXT NOT NULL REFERENCES tasks (id), "title" TEXT NOT NULL, "is_done" INTEGER NOT NULL CHECK ("is_done" IN (0, 1)), "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "tags" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "color" TEXT NOT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "task_folders" ("task_id" TEXT NOT NULL REFERENCES tasks (id), "folder_id" TEXT NOT NULL REFERENCES folders (id), PRIMARY KEY ("task_id", "folder_id"));
CREATE TABLE "task_tags" ("task_id" TEXT NOT NULL REFERENCES tasks (id), "tag_id" TEXT NOT NULL REFERENCES tags (id), PRIMARY KEY ("task_id", "tag_id"));
CREATE TABLE "tasks" ("id" TEXT NOT NULL, "origin" TEXT NOT NULL, "status" TEXT NOT NULL, "title" TEXT NOT NULL, "due_date" INTEGER NULL, "priority" TEXT NULL, "memo" TEXT NULL, "parent_task_id" TEXT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "completed_at" INTEGER NULL, "deleted_at" INTEGER NULL, "sort_order" INTEGER NOT NULL DEFAULT 0, "ecampus_source_key" TEXT NULL UNIQUE, "ecampus_source_title" TEXT NULL, "ecampus_source_due_date" INTEGER NULL, "ecampus_source_course" TEXT NULL, "ecampus_source_type" TEXT NULL, "ecampus_last_synced_at" INTEGER NULL, PRIMARY KEY ("id"));
